package com.jnapanam.sportszone.loyalty.model;import com.jnapanam.sportszone.identity.model.User;import com.jnapanam.sportszone.payment.model.PaymentOrder;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="loyalty_transactions")public class LoyaltyTransaction{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="payment_order_id")private PaymentOrder paymentOrder;@Enumerated(EnumType.STRING)@Column(name="transaction_type",nullable=false,length=20)private LoyaltyTransactionType type;@Column(nullable=false)private long points;@Column(nullable=false,length=250)private String description;@Column(name="created_at",nullable=false)private Instant createdAt;protected LoyaltyTransaction(){}public LoyaltyTransaction(User u,PaymentOrder o,LoyaltyTransactionType t,long p,String d){id=UUID.randomUUID();user=u;paymentOrder=o;type=t;points=p;description=d;createdAt=Instant.now();}public LoyaltyTransactionType getType(){return type;}public long getPoints(){return points;}public String getDescription(){return description;}public Instant getCreatedAt(){return createdAt;}}
